import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter,Routes,Route,NavLink,useNavigate,useParams,useLocation,Navigate} from 'react-router-dom';
import {QueryClient,QueryClientProvider,useQuery,useQueryClient} from '@tanstack/react-query';
import {useTranslation} from 'react-i18next';
import {Home,Building2,GitBranch,MessageSquare,BookOpen,Sparkles,Settings,ArrowUpRight,ArrowRight,Plus,Search,Bell,ChevronDown,ChevronRight,Globe,LogOut,ShieldCheck,Check,CheckCircle2,X,FileText,Upload,Download,Link,ThumbsUp,ThumbsDown,Send,Square,PanelRight,Paperclip,MoreHorizontal,History,Eye,Layers,Activity,Mail,LayoutDashboard,LoaderCircle,ArrowLeft,Pin,Archive,Copy,GripVertical,Map,AlertCircle,RefreshCw,Trash2,Folder,ExternalLink} from 'lucide-react';
import ReactMarkdown from 'react-markdown';import remarkGfm from 'remark-gfm';
import {EditorContent,useEditor} from '@tiptap/react';import StarterKit from '@tiptap/starter-kit';
import i18n from './i18n';import {api,download,setCsrf,csrf} from './api';import {Button,Badge,Empty,Modal,FormModal,PageHeader,Field} from './ui';import './styles.css';
type Item={id:string,title:string,status:string,data:Record<string,any>,version:number,created?:string,updated?:string,created_by?:string};
const client=new QueryClient({defaultOptions:{queries:{retry:false,refetchOnWindowFocus:false}}});
const AppContext=createContext<any>(null);const useApp=()=>useContext(AppContext);
const sections=['overview','products','markets','manufacturing','supply_chain','competitive','opportunities','questions'];
const icons:Record<string,any>={home:Home,profile:Building2,workflows:GitBranch,chats:MessageSquare,knowledge:BookOpen,'ai-use-cases':Sparkles,feedback:MessageSquare,settings:Settings};
function useItems(kind:string){const {base}=useApp();return useQuery<Item[]>({queryKey:[base,kind],queryFn:()=>api(base+'/records/'+kind),refetchInterval:kind==='source'?7000:false});}
function useRefresh(){const q=useQueryClient();return ()=>q.invalidateQueries();}
function Markdown({text}:{text:string}){return <div className="markdown"><ReactMarkdown remarkPlugins={[remarkGfm]} skipHtml urlTransform={u=>/^(https?:\/\/|\/|#)/.test(u)?u:''}>{text}</ReactMarkdown></div>}
function App(){
 const [error,setError]=useState('');const [notice,setNotice]=useState('');const session=useQuery({queryKey:['session'],queryFn:()=>api('/auth/me')});
 useEffect(()=>{if(session.data?.csrf)setCsrf(session.data.csrf)},[session.data]);
 useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),5000);return ()=>clearTimeout(id)}},[notice]);
 const run=async(fn:()=>Promise<any>)=>{try{const v=await fn();client.invalidateQueries();return v}catch(e){setError((e as Error).message);return null}};
 if(session.isPending)return <div className="loading-screen"><div className="brand-symbol">m</div><LoaderCircle className="spin"/></div>;
 return <AppContext.Provider value={{session:session.data,run,setError,setNotice}}><Routes><Route path="/login" element={<Auth/>}/><Route path="/invite/:token" element={<Auth mode="invite"/>}/><Route path="/reset" element={<Auth mode="reset"/>}/><Route path="/health" element={<Health/>}/><Route path="/*" element={session.data?<Shell/>:<Navigate to="/login"/>}/></Routes>{error&&<Modal title={i18n.t('failure')} onClose={()=>setError('')}><div className="error">{error}</div><div className="modal-actions"><Button onClick={()=>setError('')}>{i18n.t('close')}</Button></div></Modal>}{notice&&<div className="toast"><CheckCircle2 size={18}/>{notice}</div>}</AppContext.Provider>
}
function Auth({mode='login'}:{mode?:string}){
 const {t}=useTranslation();const {session,run}=useApp();const nav=useNavigate();const {token}=useParams();const [reset,setReset]=useState(false);const [pending,setPending]=useState<any>(null);const [secret,setSecret]=useState('');const [codes,setCodes]=useState<string[]>([]);const [busy,setBusy]=useState(false);const [email,setEmail]=useState('company@demo.local');const [pass,setPass]=useState('MiyazakiDemo2026!');const [lang,setLang]=useState(i18n.language);
 const login=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const data=Object.fromEntries(new FormData(e.currentTarget));const r=await run(async()=>{
 if(reset){await api('/auth/reset-request','POST',data);return {reset:true}}
 if(mode==='invite'||mode==='reset'){await api(mode==='invite'?'/auth/accept':'/auth/reset','POST',{...data,token:token||new URLSearchParams(location.search).get('token'),terms:data.terms==='on',language:lang});nav('/login');return null}
 return api('/auth/login','POST',{email,password:pass});});setBusy(false);if(r?.reset){setReset(false);return}if(r?.csrf){setCsrf(r.csrf);if(r.mfa_pending){setPending(r);return}await client.invalidateQueries({queryKey:['session']});nav(r.user.role.includes('Admin')&&!['Company Admin'].includes(r.user.role)?'/admin':'/');}};
 return <div className="auth-page"><aside className="auth-story"><a className="brand brand-light" href="/login"><div className="brand-symbol">m<span>✳</span></div><div>miyazaki<span>INDUSTRIAL AI COPILOT</span></div></a><div className="story-main"><div className="eyebrow">MIYAZAKI · MANUFACTURING INTELLIGENCE</div><h1>{t('welcome')}</h1><p>{t('welcomeSub')}</p><div className="story-lines"><div><ShieldCheck size={19}/>{t('evidence')}</div><div><CheckCircle2 size={19}/>{t('human')}</div><div><Globe size={19}/>{t('bilingual')}</div></div></div><div className="auth-bottom">ATOMIC LOOPS <span>×</span> MIYAZAKI</div><svg className="auth-art" viewBox="0 0 600 400"><path d="M0 340L190 140 300 250 410 90 600 330"/><path d="M0 370L190 170 300 280 410 120 600 360"/><path d="M0 400L190 200 300 310 410 150 600 390"/></svg></aside><main className="auth-form"><div className="language-switch"><button onClick={()=>{i18n.changeLanguage('ja');localStorage.setItem('language','ja');setLang('ja')}} className={i18n.language==='ja'?'selected':''}>日本語</button><button onClick={()=>{i18n.changeLanguage('en');localStorage.setItem('language','en');setLang('en')}} className={i18n.language==='en'?'selected':''}>English</button></div><div className="auth-card"><div className="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>{t(mode==='invite'?'acceptInvite':mode==='reset'||reset?'reset':'signin')}</h2><p>{t('noNetwork')}</p>{pending?<><div className="field">{t('code')}</div>{secret&&<div className="codebox">{secret}</div>}<form onSubmit={async e=>{e.preventDefault();const code=String(new FormData(e.currentTarget).get('code'));const r=await run(()=>api('/auth/mfa/verify','POST',{code}));if(r){setCodes(r.recovery_codes||[]);if(!r.recovery_codes?.length){client.invalidateQueries();nav('/')}}}}><input name="code" placeholder={t('code')} required/><div className="modal-actions">{!secret&&<Button type="button" variant="outline" onClick={async()=>{const r=await run(()=>api('/auth/mfa/enroll','POST',{}));if(r)setSecret(r.secret)}}>{t('enroll')}</Button>}<Button>{t('verify')}</Button></div></form>{codes.length>0&&<><pre>{codes.join('\n')}</pre><Button onClick={()=>{client.invalidateQueries();nav('/')}}>{t('next')}</Button></>}</>:<form onSubmit={login}>{mode==='invite'&&<label className="field"><span>{t('name')}</span><input name="name" required/></label>}{mode==='login'&&<label className="field"><span>{t('email')}</span><input name="email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label>}{!reset&&<label className="field"><span>{t('password')}</span><input name="password" type="password" minLength={12} value={pass} onChange={e=>setPass(e.target.value)} required/></label>}{mode==='invite'&&<label className="check-label"><input name="terms" type="checkbox" required/>{t('terms')}</label>}<Button className="full" disabled={busy}>{busy?<LoaderCircle size={18} className="spin"/>:null}{t(reset?'reset':mode==='invite'?'acceptInvite':mode==='reset'?'reset':'signin')}<ArrowRight size={17}/></Button></form>}{mode==='login'&&!pending&&<button className="text-link" onClick={()=>setReset(!reset)}>{t('forgot')}</button>}{mode==='login'&&<div className="demo-login"><Badge tone="amber">{t('credentials')}</Badge><p>company@demo.local · admin@demo.local<br/>platform@demo.local · other@demo.local</p><small>MiyazakiDemo2026!</small></div>}</div><div className="auth-caption">{t('demo')}</div></main></div>
}
function Shell(){
 const {session,run,setNotice}=useApp();const {t}=useTranslation();const nav=useNavigate();const loc=useLocation();const [feedback,setFeedback]=useState(false);const [notify,setNotify]=useState(false);const [tour,setTour]=useState(false);const [firstEntry,setFirstEntry]=useState(!!session.user.preferences?.first_entry);const [filter,setFilter]=useState('');const admin=loc.pathname.startsWith('/admin');const m=loc.pathname.match(/^\/w\/([^/]+)/);const wid=m?.[1]||session.workspaces?.[0]?.slug;const base='/w/'+wid;const ws=session.workspaces?.find((w:any)=>w.slug===wid||w.id===wid);const isAdmin=['Super Admin','Platform Admin'].includes(session.user.role);
 const notifications=useQuery<Item[]>({queryKey:[base,'notification'],queryFn:()=>api(base+'/records/notification'),enabled:!!wid&&!admin,refetchInterval:20000});
 const workspaceContext={...useApp(),base,wid,ws,filter,setFilter};
 if(session.mfa_pending)return <Navigate to="/login"/>;
 if(loc.pathname==='/'&&isAdmin)return <Navigate to="/admin"/>;
 if(loc.pathname==='/'&&wid)return <Navigate to={base+'/home'}/>;
 if(!admin&&!wid)return <div className="empty">No workspace has been granted. <Button onClick={()=>run(async()=>{await api('/auth/logout','POST',{});location.href='/login'})}>{t('logout')}</Button></div>;
 const menu=admin?[['','portfolio',LayoutDashboard],['companies','companies',Building2],['library','library',Layers],['feedback','feedback',MessageSquare],['audit','audit',ShieldCheck],['outbox','outbox',Mail]]:[['home','home',Home],['profile','profile',Building2],['workflows','workflows',GitBranch],['chats','chats',MessageSquare],['knowledge','knowledge',BookOpen],['ai-use-cases','usecases',Sparkles]];
 return <AppContext.Provider value={workspaceContext}><div className="app-shell"><aside className="sidebar"><NavLink to={admin?'/admin':base+'/home'} className="brand"><div className="brand-symbol">m<span>✳</span></div><div>miyazaki<span>INDUSTRIAL AI COPILOT</span></div></NavLink><div className="workspace-switch"><div className="workspace-monogram">{!admin&&ws?.data?.logo_source_id?<img alt="Company logo" src={'/api/v1'+base+'/sources/'+ws.data.logo_source_id+'/file'} style={{width:30,height:30,objectFit:'contain'}}/>:admin?'M':ws?.name?.slice(0,1)||'S'}</div><div><strong>{admin?'Operator console':i18n.language==='ja'?ws?.name_ja||ws?.name:ws?.name}</strong><small>{admin?'Miyazaki Prefecture':t('company')}</small></div><ChevronDown size={14}/></div><div className="nav-caption">{admin?'MANAGEMENT':'WORKSPACE'}</div><nav>{menu.map(([path,key,Icon]:any)=><NavLink key={path} to={admin?'/admin'+(path?'/'+path:''):base+'/'+path} end={path===''} className={({isActive})=>'nav-link '+(isActive?'active':'')}><Icon size={18}/><span>{t(key)}</span>{path==='ai-use-cases'&&<span className="nav-new">AI</span>}</NavLink>)}</nav>{!admin&&<div className="sidebar-note"><div className="note-spark"><Sparkles size={17}/></div><h4>{t('quick')}</h4><p>{t('evidence')}</p><button onClick={()=>nav(base+'/chats')}>{t('newChat')}<ArrowUpRight size={14}/></button></div>}<div className="sidebar-bottom">{!admin&&<NavLink to={base+'/settings'} className="nav-link"><Settings size={18}/>{t('settings')}</NavLink>}<button className="nav-link" onClick={()=>setTour(true)}><BookOpen size={18}/>{t('help')}</button><NavLink to="/health" className="nav-link"><Activity size={18}/>{t('health')}</NavLink>{isAdmin&&!admin&&<NavLink to="/admin" className="nav-link"><ShieldCheck size={18}/>{t('portfolio')}</NavLink>}<div className="user-card"><div className="avatar">{session.user.name.slice(0,1)}</div><div><strong>{session.user.name}</strong><small>{session.user.role}</small></div><button aria-label={t('logout')} className="icon-btn" onClick={()=>run(async()=>{await api('/auth/logout','POST',{});location.href='/login'})}><LogOut size={16}/></button></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb">{admin?t('portfolio'):ws?.name||'Workspace'}<ChevronRight size={12}/><span>{t(menu.find(([path]:any)=>loc.pathname.includes('/'+path))?.[1] as string||'home')}</span></div><div className="top-actions"><div className="search-box"><Search size={15}/><input placeholder={t('search')} value={filter} onChange={e=>setFilter(e.target.value)}/><kbd>⌕</kbd></div><button className="lang-button" onClick={async()=>{const lang=i18n.language==='ja'?'en':'ja';i18n.changeLanguage(lang);localStorage.setItem('language',lang);await run(()=>api('/auth/preferences','PATCH',{language:lang}))}}><Globe size={15}/>{i18n.language==='ja'?'日本語':'English'}<ChevronDown size={12}/></button>{!admin&&<button className="icon-btn notification-button" aria-label={t('notify')} onClick={()=>setNotify(true)}><Bell size={18}/>{notifications.data?.some(n=>n.status==='Unread')&&<i/>}</button>}<div className="avatar small">{session.user.name.slice(0,1)}</div></div></header><div className="demo-ribbon"><span><span className="status-dot"/>{t('demo')}</span><span>{session.demo_mfa_bypass?t('mfaNotice'):t('human')}</span></div><main className="page-content"><Routes><Route path="/admin/*" element={<Admin/>}/><Route path="/w/:company/home" element={<Overview onTour={()=>setTour(true)}/>}/><Route path="/w/:company/profile" element={<Profile/>}/><Route path="/w/:company/workflows/*" element={<Workflows/>}/><Route path="/w/:company/chats/*" element={<Chats/>}/><Route path="/w/:company/knowledge/*" element={<Knowledge/>}/><Route path="/w/:company/ai-use-cases/*" element={<UseCases/>}/><Route path="/w/:company/feedback" element={<FeedbackPage/>}/><Route path="/w/:company/settings" element={<WorkspaceSettings/>}/><Route path="*" element={<Navigate to={base+'/home'}/>}/></Routes></main></div>{!admin&&<button className="feedback-fab" onClick={()=>setFeedback(true)}><MessageSquare size={17}/>{t('feedback')}</button>}{feedback&&<FeedbackModal onClose={()=>setFeedback(false)}/>} {firstEntry&&<Onboarding onClose={()=>{setFirstEntry(false);run(()=>api('/auth/preferences','PATCH',{first_entry:false}))}}/>} {tour&&<Modal title={t('tourTitle')} onClose={()=>setTour(false)}><div className="tour-art"><Layers size={50}/><ArrowRight/><ShieldCheck size={50}/><ArrowRight/><Sparkles size={50}/></div><p>{t('tourBody')}</p><p className="subtle">{t('ocrNotice')}</p><div className="modal-actions"><Button onClick={()=>{localStorage.setItem('tour-seen','true');setTour(false)}}>{t('next')}<ArrowRight size={16}/></Button></div></Modal>}{notify&&<Modal title={t('notify')} onClose={()=>setNotify(false)}>{notifications.data?.length?notifications.data.map(n=><div className="list-row" key={n.id}><Bell size={16}/><div><strong>{n.title}</strong><small>{new Date(n.created||'').toLocaleString(i18n.language)}</small></div><Button variant="ghost" onClick={()=>run(()=>api(base+'/records/'+n.id,'PATCH',{status:'Read'}))}><Check size={15}/></Button></div>):<Empty text={t('empty')}/>}</Modal>}</div></AppContext.Provider>
}
function Overview({onTour}:{onTour:()=>void}){
 const {base,ws,run}=useApp();const {t}=useTranslation();const nav=useNavigate();const [intro,setIntro]=useState(false);const {data:h}=useQuery({queryKey:[base,'home'],queryFn:()=>api(base+'/home')});const workflows=useItems('workflow');const docs=useItems('document');
 return <><PageHeader eyebrow="YOUR WORKSPACE, AT A GLANCE" title={(i18n.language==='ja'?'こんにちは、':'Welcome back, ')+(i18n.language==='ja'?ws?.name_ja||ws?.name:ws?.name)} description={t('quickSub')} actions={<Button onClick={()=>setIntro(true)}><Plus size={16}/>{t('onboarding')}</Button>}/>{h?.usage?.warning&&<div className="warning">{t('budget')}: {h.usage.used.toLocaleString(i18n.language)} / {h.usage.budget.toLocaleString(i18n.language)} (80%+)</div>}<div className="hero-panel"><div className="hero-copy"><Badge tone="light"><Sparkles size={12}/> INDUSTRIAL INTELLIGENCE</Badge><h2>{t('quick')}</h2><p>{t('welcomeSub')}</p><div className="hero-actions"><Button onClick={()=>nav(base+'/chats')}>{t('newChat')}<ArrowUpRight size={16}/></Button><button className="hero-link" onClick={onTour}>{t('help')}<ArrowRight size={15}/></button></div></div><div className="hero-visual"><svg viewBox="0 0 360 220"><g fill="none" stroke="#789b83" strokeWidth="1"><path d="M20 165L180 72 340 165 180 255Z"/><path d="M20 135L180 42 340 135 180 225Z"/><path d="M20 105L180 12 340 105 180 195Z"/></g><g fill="#244c37" stroke="#8db199"><path d="M90 105L135 79 180 105 135 132Z"/><path d="M90 105V145L135 172V132Z"/><path d="M135 132L180 105V145L135 172Z"/><path d="M180 105L225 79 270 105 225 132Z"/><path d="M180 105V145L225 172V132Z"/><path d="M225 132L270 105V145L225 172Z"/><path d="M135 39L180 13 225 39 180 66Z"/><path d="M135 39V99L180 126V66Z"/><path d="M180 66L225 39V99L180 126Z"/></g><circle cx="180" cy="13" r="5" fill="#d7f0a2"/><path d="M180 13V0" stroke="#d7f0a2"/></svg><div className="visual-tag"><span className="status-dot"/> {t('evidence')}</div></div></div><div className="stats-grid"><Stat label={t('completeness')} value={(h?.completeness?.overall||0)+'%'} icon={Building2} trend={t('confirmed')}/><Stat label={t('workflows')} value={h?.counts?.workflow||0} icon={GitBranch} trend={t('start')}/><Stat label={t('documents')} value={h?.counts?.document||0} icon={FileText} trend={t('knowledge')}/><Stat label={t('usecases')} value={h?.counts?.usecase||0} icon={Sparkles} trend={t('opportunities')}/></div><div className="overview-grid"><section className="card"><div className="card-heading"><h3>{t('gaps')}</h3><Badge>{h?.completeness?.gaps?.length||0}</Badge></div>{h?.completeness?.top_gaps?.map((g:any,i:number)=><button className="gap-row" key={g.key} onClick={()=>nav(base+'/profile')}><div className="step-number">0{i+1}</div><div><strong>{t(g.section)}</strong><p>{g.key.replaceAll('_',' ')}</p></div><ArrowUpRight size={17}/></button>)}<button className="card-footer-link" onClick={()=>nav(base+'/profile')}>{t('profile')}<ArrowRight size={15}/></button></section><section className="card"><div className="card-heading"><h3>{t('completeness')}</h3><Building2 size={17}/></div><div className="progress-sections">{Object.entries(h?.completeness?.sections||{}).map(([s,v]:any)=><div key={s}><span>{t(s)}</span><div className="progress-track"><i style={{width:v+'%'}}/></div><strong>{v}%</strong></div>)}</div><div className="small-note"><ShieldCheck size={14}/>{t('human')}</div></section></div><div className="section-heading"><h2>{t('workflows')}</h2><button className="text-link" onClick={()=>nav(base+'/workflows')}>{t('all')}<ArrowRight size={15}/></button></div><div className="workflow-preview-grid">{workflows.data?.slice(0,3).map(w=><button className="card workflow-preview" key={w.id} onClick={()=>nav(base+'/workflows/'+w.id)}><div className="preview-icon"><GitBranch size={22}/></div><Badge tone="amber">{w.status}</Badge><h3>{i18n.language==='ja'?({B1:'企業ディスカバリー',B3:'市場と製品市場適合',B4:'製造とAIの準備状況'} as any)[w.data.template]||w.title:w.title}</h3><p>{i18n.language==='ja'?w.data.rationale_ja:w.data.rationale}</p><div className="preview-footer">{w.data.steps?.length} {t('step')}<ArrowUpRight size={16}/></div></button>)}<button className="card new-preview" onClick={()=>nav(base+'/workflows')}><Plus size={24}/><span>{t('proposeWorkflows')}</span></button></div>{intro&&<Onboarding onClose={()=>setIntro(false)}/>}</>
}
function Stat({label,value,icon:Icon,trend}:{label:string,value:any,icon:any,trend?:string}){return <div className="stat card"><div className="stat-top"><span>{label}</span><Icon size={17}/></div><strong>{value}</strong>{trend&&<small><span className="mini-dot"/>{trend}</small>}</div>}
function Onboarding({onClose}:{onClose:()=>void}){const {base,run}=useApp();const {t}=useTranslation();return <FormModal title={t('onboarding')} onClose={onClose} fields={[{name:'url',label:t('website'),required:false},{name:'product',label:t('productText'),type:'textarea',required:false},{name:'employees',label:t('employee'),required:false},{name:'plants',label:t('plants'),required:false},{name:'certifications',label:t('certifications'),required:false}]} onSubmit={async d=>{await api(base+'/settings','PATCH',{data:{onboarding:d}});for(const key of ['employees','plants','certifications','product'])if(d[key])await api(base+'/facts','POST',{data:{section:key==='certifications'?'manufacturing':key==='product'?'products':'overview',key,value:d[key],provenance:'Stated',confidence:1,sources:[]}});await api(base+'/sources/crawl','POST',{url:d.url,fixture:!d.url});client.invalidateQueries()}}><p className="small-note">{t('ocrNotice')}</p></FormModal>}
function Profile(){
 const {base,filter,run}=useApp();const {t}=useTranslation();const facts=useItems('fact');const products=useItems('product');const [section,setSection]=useState('all');const [state,setState]=useState('all');const [form,setForm]=useState<any>(null);const [history,setHistory]=useState<any>(null);const [why,setWhy]=useState<Item|null>(null);const {data:home}=useQuery({queryKey:[base,'home'],queryFn:()=>api(base+'/home')});
 const items=facts.data?.filter(f=>(section==='all'||f.data.section===section)&&(state==='all'||f.status===state)&&JSON.stringify(f).toLowerCase().includes(filter.toLowerCase()))||[];
 const review=(f:Item,action:string)=>run(()=>api(base+'/facts/'+f.id+'/'+action,'POST',{version:f.version}));
 return <><PageHeader eyebrow="A SHARED UNDERSTANDING" title={t('profile')} description={t('evidence')} actions={<><Button variant="outline" onClick={()=>download(base+'/export/profile/current?format=pdf')}><Download size={15}/>PDF</Button><Button variant="outline" onClick={()=>download(base+'/export/profile/current?format=docx')}>DOCX</Button><Button onClick={()=>setForm({type:'new'})}><Plus size={16}/>{t('newFact')}</Button></>}/><div className="profile-banner"><div className="ring" style={{'--percent':home?.completeness?.overall||0} as any}><span>{home?.completeness?.overall||0}%</span></div><div><h3>{t('completeness')}</h3><p>{t('human')}</p></div><div className="provenance-legend"><Badge tone="green">{t('stated')}</Badge><Badge tone="blue">{t('sourced')}</Badge><Badge tone="amber">{t('inferred')}</Badge></div></div><div className="profile-layout"><aside className="section-nav">{['all',...sections].map(s=><button key={s} className={section===s?'active':''} onClick={()=>setSection(s)}>{t(s)}<span>{facts.data?.filter(f=>s==='all'||f.data.section===s).length||0}</span></button>)}<div className="small-note"><Eye size={15}/>{t('sharing')}</div><div className="product-list"><h4>{t('products')}</h4>{products.data?.filter(p=>!['Merged','Deleted'].includes(p.status)).map(p=><button className="product-chip" key={p.id} onClick={()=>setForm({type:'product',item:p})}>{p.title}<ChevronRight size={13}/></button>)}<Button variant="ghost" onClick={()=>setForm({type:'product'})}><Plus size={14}/>{t('products')}</Button></div></aside><section><div className="tabs compact">{['all','Proposed','Confirmed','Rejected','Disputed'].map(s=><button key={s} className={state===s?'active':''} onClick={()=>setState(s)}>{t(({Proposed:'review',Confirmed:'confirmed',Rejected:'rejected',Disputed:'dispute'} as any)[s]||s)}</button>)}</div>{items.length?items.map(f=><article className="fact-card card" key={f.id}><div className="fact-meta"><span>{t(f.data.section)}</span><Badge tone={f.data.provenance==='Stated'?'green':f.data.provenance==='Sourced'?'blue':'amber'}>{t(f.data.provenance?.toLowerCase()||'inferred')}</Badge><span className="confidence">{Math.round((f.data.confidence||0)*100)}% {t('confidence')}</span><Badge>{f.status}</Badge></div><h3>{f.title.replaceAll('_',' ')}</h3><p className="fact-value">{String(f.data.translations?.[i18n.language]||f.data.value)}</p>{f.data.translations?.[i18n.language]&&<small className="subtle">{t('translated')} · {String(f.data.value)}</small>}{f.data.conflict&&<div className="warning">Conflicting value — review required</div>}{f.data.synthetic&&<small className="subtle">{t('demo')}</small>}<div className="fact-actions"><Button variant="outline" onClick={()=>review(f,'confirm')}><Check size={14}/>{t('confirm')}</Button><Button variant="ghost" onClick={()=>setForm({type:'edit',item:f})}>{t('edit')}</Button><Button variant="ghost" onClick={()=>review(f,'reject')}>{t('reject')}</Button><button className="text-link" onClick={()=>setWhy(f)}>{t('why')}</button><button className="icon-btn" aria-label={t('translate')} onClick={()=>run(()=>api(base+'/translate/'+f.id,'POST',{language:i18n.language==='ja'?'en':'ja'}))}><Globe size={14}/></button><button className="icon-btn push" aria-label={t('history')} onClick={async()=>{const r=await run(()=>api(base+'/history/'+f.id));if(r)setHistory(r)}}><History size={16}/></button><button className="icon-btn" aria-label={t('dispute')} onClick={()=>review(f,'dispute')}><AlertCircle size={16}/></button><Rating target={f.id} feature="profile"/></div></article>):<Empty text={t('empty')}/>}</section></div>{form&&<FormModal title={t(form.type==='new'?'newFact':form.type==='product'?'products':'edit')} onClose={()=>setForm(null)} fields={form.type==='product'?[{name:'title',label:t('name'),value:form.item?.title},{name:'function',label:t('content'),type:'textarea',value:form.item?.data.function||''},...['materials','process','customers','differentiators','potential'].map(k=>({name:k,label:k,type:'textarea',value:form.item?.data[k]||''})),{name:'merge',label:t('merge'),options:['None',...(products.data||[]).filter(p=>p.id!==form.item?.id&&p.status!=='Merged'&&p.status!=='Deleted').map(p=>p.title)],required:false}]:[{name:'section',label:t('section'),options:sections,value:form.item?.data.section||'overview'},{name:'key',label:t('key'),value:form.item?.data.key},{name:'value',label:t('value'),type:'textarea',value:form.item?.data.value}]} onSubmit={async d=>{if(form.type==='product'){await api(base+'/records/'+(form.item?form.item.id:'product'),form.item?'PATCH':'POST',{title:d.title,data:Object.fromEntries(Object.entries(d).filter(([k])=>k!=='title'&&k!=='merge'))});if(form.item&&d.merge&&d.merge!=='None'){const other=products.data?.find(p=>p.title===d.merge);if(other)await api(base+'/products/'+form.item.id+'/merge','POST',{other_id:other.id})}}else if(form.type==='edit')await api(base+'/facts/'+form.item.id+'/edit','POST',{version:form.item.version,data:d});else await api(base+'/facts','POST',{data:{...d,provenance:'Stated',confidence:1,sources:[]}});client.invalidateQueries()}}/>}{history&&<Modal title={t('history')} onClose={()=>setHistory(null)}>{history.length?history.map((r:any)=><div className="history-item" key={r.id}><Badge>v{r.version}</Badge><small>{new Date(r.time).toLocaleString(i18n.language)}</small><p>{r.snapshot.data.value}</p><Badge>{r.snapshot.status}</Badge></div>):<Empty text={t('empty')}/>}</Modal>}{why&&<Modal title={t('why')} onClose={()=>setWhy(null)}><p>{why.data.why||t('evidence')}</p><p className="subtle">{why.data.provenance} · {Math.round(why.data.confidence*100)}%</p>{why.data.sources?.map((id:string)=><p key={id}><Badge>{id}</Badge></p>)}</Modal>}</>
}
function Workflows(){
 const {base,filter,run}=useApp();const {t}=useTranslation();const nav=useNavigate();const loc=useLocation();const items=useItems('workflow');const id=loc.pathname.split('/workflows/')[1];const selected=items.data?.find(w=>w.id===id);const [pending,setPending]=useState<Item|null>(null);const [stepIndex,setStepIndex]=useState(0);const [assign,setAssign]=useState<any>(null);const [answers,setAnswers]=useState<Record<string,string>>({});
 const propose=async(w:Item,action:string,status:string,step_id?:string)=>{const r=await run(()=>api(base+'/pending','POST',{title:w.title,data:{action,target_id:w.id,status,step_id}}));if(r)setPending(r)};
 const step=selected?.data.steps?.[stepIndex];
 return <><PageHeader eyebrow="SMALL QUESTIONS. BETTER DECISIONS." title={selected?.title||t('workflows')} description={t('tourBody')} actions={<><Button variant="outline" onClick={()=>run(()=>api(base+'/workflows/propose','POST',{}))}><Sparkles size={16}/>{t('proposeWorkflows')}</Button>{selected&&<Button onClick={()=>selected.data.chat_id?nav(base+'/chats/'+selected.data.chat_id):propose(selected,'workflow_status','Active')}><MessageSquare size={16}/>{t('chats')}</Button>}</>}/>{selected?<><button className="text-link" onClick={()=>nav(base+'/workflows')}><ArrowLeft size={15}/>{t('all')}</button><div className="workflow-detail"><aside className="card stepper">{selected.data.steps.map((s:any,i:number)=><button key={s.id} onClick={()=>setStepIndex(i)} className={stepIndex===i?'active':''}><span className={'step-circle '+(s.status==='Done'?'done':'')}>{s.status==='Done'?<Check size={15}/>:i+1}</span><div><strong>{t(s.type==='questions'?'questionsTab':s.type==='upload'?'upload':s.type==='review'?'review':s.type)}</strong><small>{s.status}</small></div><ChevronRight size={14}/></button>)}<div className="dependency-box"><h4>{t('dependencies')}</h4>{selected.data.steps.map((s:any,i:number)=><div key={s.id}><span>{i+1}</span><span className="dependency-line"/> {s.feeds.join(' + ')}</div>)}</div></aside><section className="card step-content"><div className="eyebrow">{t('step')} {stepIndex+1} / {selected.data.steps.length}</div><h2>{t(step?.type==='questions'?'questionsTab':step?.type==='upload'?'upload':step?.type==='review'?'review':step?.type||'step')}</h2><div className="step-meta"><Badge>{step?.status}</Badge><small>{t('owner')}: {step?.owner}</small></div>{step?.type==='questions'&&step.questions.map((q:any)=><div className="question" key={q.key}><label>{i18n.language==='ja'?q.text_ja:q.text}</label><textarea rows={2} value={answers[q.key]??q.answer} onChange={e=>setAnswers({...answers,[q.key]:e.target.value})}/><div className="row-actions"><Button variant="outline" onClick={()=>run(()=>api(base+'/workflows/'+selected.id+'/answer','POST',{step_id:step.id,key:q.key,value:answers[q.key]??q.answer}))}>{t('saveProgress')}</Button><Button variant="ghost" onClick={()=>run(()=>api(base+'/workflows/'+selected.id+'/answer','POST',{step_id:step.id,key:q.key,unknown:true}))}>{t('unknown')}</Button><button className="text-link" onClick={()=>setAssign(q)}>{t('assign')}</button></div></div>)}{step?.type==='upload'&&<UploadPanel/>}{step?.type==='analysis'&&<><p>{t('evidence')}</p><JobsPanel/><Button onClick={()=>run(()=>api(base+'/sources/crawl','POST',{fixture:true}))}><Sparkles size={15}/>{t('analysis')}</Button></>}{step?.type==='review'&&<><p>{t('human')}</p><Button variant="outline" onClick={()=>nav(base+'/profile')}>{t('review')}<ArrowUpRight size={15}/></Button></>}{step?.type==='output'&&<><p>{t('documents')} · {t('profile')}</p>{selected.data.outputs?.map((o:string)=><Button key={o} variant="outline" onClick={()=>nav(base+'/knowledge/documents/'+o)}>{t('view')}</Button>)}</>}<div className="step-complete"><Button variant="outline" onClick={()=>propose(selected,'step_status','Skipped',step.id)}>{t('defer')}</Button><Button onClick={()=>propose(selected,'step_status','Done',step.id)}><Check size={15}/>{t('complete')}</Button></div></section></div></>:<div className="workflow-grid">{items.data?.filter(w=>w.title.toLowerCase().includes(filter.toLowerCase())).map(w=><article className="card workflow-card" key={w.id}><div className="card-heading"><div className="preview-icon"><GitBranch size={22}/></div><Badge tone={w.status==='Done'?'green':'amber'}>{w.status}</Badge></div><h3>{i18n.language==='ja'?({B1:'企業ディスカバリー',B2:'製品の深掘り',B3:'市場と製品市場適合',B4:'製造とAIの準備状況'} as any)[w.data.template]||w.title:w.title}</h3><p>{i18n.language==='ja'?w.data.rationale_ja:w.data.rationale}</p><div className="workflow-count">{w.data.steps?.filter((s:any)=>s.status==='Done').length||0} / {w.data.steps?.length} {t('step')}</div><div className="progress-track"><i style={{width:((w.data.steps?.filter((s:any)=>s.status==='Done').length||0)/(w.data.steps?.length||1))*100+'%'}}/></div><div className="row-actions"><Button onClick={()=>w.status==='Proposed'?propose(w,'workflow_status','Active'):nav(base+'/workflows/'+w.id)}>{t(w.status==='Proposed'?'start':'view')}<ArrowRight size={15}/></Button><Button variant="ghost" onClick={()=>propose(w,'workflow_status','Deferred')}>{t('defer')}</Button><button className="icon-btn" aria-label={t('dismiss')} onClick={()=>propose(w,'workflow_status','Dismissed')}><X size={15}/></button></div></article>)}<button className="card new-preview" onClick={()=>run(()=>api(base+'/workflows/propose','POST',{}))}><Sparkles size={28}/>{t('proposeWorkflows')}</button></div>}{pending&&<Modal title={t('reviewActions')} onClose={()=>setPending(null)}><h3>{pending.title}</h3><dl className="detail-list">{Object.entries(pending.data).filter(([k])=>['status','action','step_id'].includes(k)).map(([k,v])=><div key={k}><dt>{k.replaceAll('_',' ')}</dt><dd>{String(v)}</dd></div>)}</dl><div className="modal-actions"><Button variant="ghost" onClick={()=>setPending(null)}>{t('cancel')}</Button><Button onClick={async()=>{const r=await run(()=>api(base+'/pending/'+pending.id+'/confirm','POST',{}));if(r){setPending(null);if(r.result)nav(base+'/workflows/'+r.result)}}}>{t('confirm')}</Button></div></Modal>}{assign&&selected&&<FormModal title={t('assign')} fields={[{name:'email',label:t('email')}]} onClose={()=>setAssign(null)} onSubmit={async d=>{await api(base+'/workflows/'+selected.id+'/answer','POST',{step_id:step.id,key:assign.key,assigned_to:d.email,value:assign.answer});client.invalidateQueries()}}/>}</>
}
function Chats(){
 const {base,run,setNotice}=useApp();const {t}=useTranslation();const nav=useNavigate();const loc=useLocation();const chats=useItems('chat');const allMessages=useItems('message');const sources=useItems('source');const facts=useItems('fact');const id=loc.pathname.split('/chats/')[1];const selected=chats.data?.find(c=>c.id===id);const [input,setInput]=useState('');const [stream,setStream]=useState('');const [busy,setBusy]=useState(false);const [contextOpen,setContextOpen]=useState(true);const [selection,setSelection]=useState<any>({profile:true,knowledge:true,workflow:true});const [form,setForm]=useState<any>(null);const [pending,setPending]=useState<any>(null);const [files,setFiles]=useState<string[]>([]);const abort=useRef<AbortController|null>(null);const end=useRef<HTMLDivElement>(null);const messages=allMessages.data?.filter(m=>m.data.chat_id===id).reverse()||[];
 useEffect(()=>end.current?.scrollIntoView({behavior:'smooth',block:'end'}),[messages.length,stream]);
 const create=async()=>{const r=await run(()=>api(base+'/records/chat','POST',{title:i18n.language==='ja'?'新しいチャット':'New conversation',data:{}}));if(r)nav(base+'/chats/'+r.id)};
 const send=async()=>{if(!input.trim()||busy)return;const text=input;setInput('');setBusy(true);setStream('');abort.current=new AbortController();try{const response=await fetch('/api/v1'+base+'/chats/'+id+'/messages',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({message:text,language:i18n.language,context:selection,attachment_ids:files}),signal:abort.current.signal});if(!response.ok){const e=await response.json();throw new Error(e.detail)}const reader=response.body!.getReader();const decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const events=buffer.split('\n\n');buffer=events.pop()||'';for(const event of events){const type=event.match(/event: (.+)/)?.[1];const data=event.split('\ndata: ')[1];if(!data)continue;const v=JSON.parse(data);if(type==='delta')setStream(s=>s+v.text);if(type==='replace')setStream(v.text);if(type==='error')throw new Error(v.message);}}}catch(e){if((e as Error).name!=='AbortError')useAppError((e as Error).message)}finally{setBusy(false);setStream('');setFiles([]);client.invalidateQueries()}};
 const app=useApp();function useAppError(s:string){app.setError(s)}
 return <><PageHeader eyebrow="A CONVERSATION WITH CONTEXT" title={t('chats')} actions={<Button onClick={create}><Plus size={16}/>{t('newChat')}</Button>}/><div className={'chat-layout '+(!contextOpen?'context-closed':'')}><aside className="chat-list card"><div className="card-heading"><h3>{t('chats')}</h3><button className="icon-btn" onClick={create} aria-label={t('newChat')}><Plus size={17}/></button></div>{chats.data?.filter(c=>!c.data.archived).sort((a,b)=>Number(!!b.data.pinned)-Number(!!a.data.pinned)).map(c=><button className={'chat-list-item '+(c.id===id?'active':'')} key={c.id} onClick={()=>nav(base+'/chats/'+c.id)}><MessageSquare size={16}/><div><strong>{c.title}</strong><small>{c.data.workflow_id?t('workflows'):t('chats')}</small></div>{c.data.pinned&&<Pin size={12}/>}</button>)}</aside><section className="conversation card"><div className="conversation-head"><div className="copilot-avatar"><Sparkles size={17}/></div><div><strong>{selected?.title||'Miyazaki Copilot'}</strong><small><span className="mini-dot"/>{t('evidence')}</small></div>{selected&&<><button className="icon-btn push" aria-label={t('rename')} onClick={()=>setForm({type:'rename',item:selected})}><MoreHorizontal size={18}/></button><button className="icon-btn" aria-label={t('pin')} onClick={()=>run(()=>api(base+'/records/'+selected.id,'PATCH',{data:{pinned:!selected.data.pinned}}))}><Pin size={16}/></button><button className="icon-btn" aria-label={t('archive')} onClick={()=>run(()=>api(base+'/records/'+selected.id,'PATCH',{data:{archived:true}}))}><Archive size={16}/></button><button className="icon-btn" aria-label={t('export')} onClick={()=>download(base+'/export/chat/'+id+'?format=pdf')}><Download size={16}/></button></>}<button className="icon-btn" aria-label={t('context')} onClick={()=>setContextOpen(!contextOpen)}><PanelRight size={18}/></button></div><div className="messages">{!messages.length&&!stream&&<div className="chat-welcome"><div className="welcome-spark"><Sparkles size={31}/></div><h2>{t('quick')}</h2><p>{t('evidence')}</p>{!selected?<Button onClick={create}>{t('newChat')}<ArrowRight size={16}/></Button>:<div className="prompt-cards">{(i18n.language==='ja'?['当社の強みを要約してください','工場のAI活用候補は？','会社紹介の構成を提案して']:['Summarise our strengths','Where could AI help our factory?','Suggest a company introduction']).map(p=><button key={p} onClick={()=>setInput(p)}>{p}<ArrowUpRight size={14}/></button>)}</div>}</div>}{messages.map(m=><div className={'message '+m.data.role} key={m.id}><div className="message-avatar">{m.data.role==='assistant'?<Sparkles size={16}/>:<span>Y</span>}</div><div className="message-body"><div className="message-author">{m.data.role==='assistant'?'Miyazaki Copilot':'You'}<small>{m.status!=='Done'?m.status:''}</small></div><Markdown text={m.data.content}/>{m.data.citations&&<div className="citation-chips">{Object.entries(m.data.citations).map(([h,c]:any)=><button key={h} onClick={()=>setForm({type:'evidence',item:c})}><Link size={11}/>{c.label}</button>)}</div>}<div className="message-actions"><button className="icon-btn" aria-label={t('copy')} onClick={()=>navigator.clipboard.writeText(m.data.content)}><Copy size={13}/></button><Rating target={m.id} feature="chat"/><button className="text-link" onClick={()=>setForm({type:'propose',item:m})}>{t('propose')}</button><button className="icon-btn" aria-label={t('saveSource')} onClick={()=>run(()=>api(base+'/messages/'+m.id+'/save-source','POST',{}))}><BookOpen size={13}/></button><button className="icon-btn" aria-label={t('toDocument')} onClick={()=>run(async()=>{const d=await api(base+'/records/document','POST',{title:'Conversation draft',data:{content:m.data.content,language:i18n.language}});nav(base+'/knowledge/documents/'+d.id)})}><FileText size={13}/></button><button className="icon-btn" aria-label={t('toWorkflow')} onClick={async()=>{const p=await run(()=>api(base+'/pending','POST',{title:t('toWorkflow'),data:{action:'chat_to_workflow',target_id:id}}));if(p)setPending(p)}}><GitBranch size={13}/></button></div></div></div>)}{(busy||stream)&&<div className="message assistant"><div className="message-avatar"><Sparkles size={16}/></div><div className="message-body"><div className="message-author">Miyazaki Copilot</div>{stream?<Markdown text={stream}/>:<div className="thinking"><i/><i/><i/>{t('working')}</div>}</div></div>}<div ref={end}/></div><form className="composer" onSubmit={e=>{e.preventDefault();send()}}><textarea placeholder={t('message')} disabled={!selected} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();send()}}}/><div className="composer-bottom"><label className="attach-btn"><Paperclip size={17}/><input hidden type="file" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;const data=new FormData();data.append('file',f);const r=await run(()=>api(base+'/sources/upload','POST',data));if(r)setFiles([...files,r.source.id])}}/></label><small>{files.length?files.length+' '+t('sources'):t('human')}</small>{busy?<Button type="button" onClick={()=>abort.current?.abort()}><Square size={14}/>{t('stop')}</Button>:<Button disabled={!selected||!input.trim()} aria-label={t('send')}><Send size={16}/></Button>}</div></form></section>{contextOpen&&<aside className="context-panel card"><div className="card-heading"><h3>{t('context')}</h3><ShieldCheck size={16}/></div>{[['profile','profile'],['knowledge','sourceToggle'],['workflow','workflowToggle']].map(([k,label])=><label className="context-toggle" key={k}><div><strong>{t(label)}</strong><small>{k==='profile'?facts.data?.filter(f=>f.status==='Confirmed').length+' '+t('confirmed'):k==='knowledge'?sources.data?.filter(s=>s.status==='Ready').length+' '+t('sources'):t('workflows')}</small></div><input type="checkbox" checked={selection[k]} onChange={e=>setSelection({...selection,[k]:e.target.checked})}/></label>)}{!selection.profile&&<div className="warning">{t('noProfile')}</div>}<div className="context-sources">{selection.profile&&sections.map(s=><label className="check-label" key={s}><input type="checkbox" checked={!selection.sections||selection.sections.includes(s)} onChange={e=>{const current=selection.sections||sections;setSelection({...selection,sections:e.target.checked?[...current,s]:current.filter((x:string)=>x!==s)})}}/>{t(s)}</label>)}{sources.data?.filter(s=>s.status==='Ready').map(s=><label className="check-label" key={s.id}><input type="checkbox" checked={!selection.sources||selection.sources.includes(s.id)} onChange={e=>{const current=selection.sources||sources.data?.filter(x=>x.status==='Ready').map(x=>x.id);setSelection({...selection,sources:e.target.checked?[...current,s.id]:current.filter((id:string)=>id!==s.id)})}}/>{s.title}</label>)}</div>{selected?.data.summary&&<div className="summary-box"><h4>{t('history')}</h4><p>{selected.data.summary}</p></div>}<div className="context-note"><ShieldCheck size={21}/><h4>{t('human')}</h4><p>{t('evidence')}</p></div></aside>}</div>{form?.type==='rename'&&<FormModal title={t('rename')} fields={[{name:'title',label:t('title'),value:form.item.title}]} onClose={()=>setForm(null)} onSubmit={async d=>{await api(base+'/records/'+id,'PATCH',{title:d.title});client.invalidateQueries()}}/>}{form?.type==='propose'&&<FormModal title={t('propose')} fields={[{name:'section',label:t('section'),options:sections},{name:'key',label:t('key')},{name:'value',label:t('value'),type:'textarea',value:form.item.data.content}]} onClose={()=>setForm(null)} onSubmit={async d=>{await api(base+'/messages/'+form.item.id+'/propose','POST',{data:d});client.invalidateQueries()}}/>}{form?.type==='evidence'&&<Modal title={t('evidence')} onClose={()=>setForm(null)}><p>{form.item.label}</p><p>{(sources.data?.find(s=>s.id===form.item.id)||facts.data?.find(s=>s.id===form.item.id))?.data.text||(facts.data?.find(s=>s.id===form.item.id))?.data.value}</p></Modal>}{pending&&<Modal title={t('reviewActions')} onClose={()=>setPending(null)}><p>{pending.title}</p><p>{t('workflows')}: B1 · 6 {t('step')}</p><div className="modal-actions"><Button onClick={async()=>{const r=await run(()=>api(base+'/pending/'+pending.id+'/confirm','POST',{}));if(r){setPending(null);nav(base+'/workflows/'+r.result)}}}>{t('confirm')}</Button></div></Modal>}</>
}
function Rating({target,feature}:{target:string,feature:string}){const {base,run,setNotice}=useApp();const {t}=useTranslation();const [done,setDone]=useState(false);return <span className="rating">{['up','down'].map(r=><button key={r} aria-label={r==='up'?'Helpful':'Not helpful'} className={'icon-btn '+(done?'rated':'')} onClick={async()=>{const v=await run(()=>api(base+'/records/feedback','POST',{title:'Output feedback',data:{rating:r,...(feature==='recommendation'?{library_id:target}:{target_id:target}),feature,page:location.pathname,language:i18n.language}}));if(v){setDone(true);setNotice(t('feedbackThanks'))}}}>{r==='up'?<ThumbsUp size={13}/>:<ThumbsDown size={13}/>}</button>)}</span>}
function UploadPanel(){const {base,run}=useApp();const {t}=useTranslation();const [busy,setBusy]=useState(false);return <label className="upload-zone"><Upload size={28}/><strong>{t('upload')}</strong><small>PDF · DOCX · XLSX · PPTX · TXT · PNG · JPG — 25 MB</small><small>{t('ocrNotice')}</small>{busy&&<LoaderCircle className="spin"/>}<input hidden type="file" onChange={async e=>{if(!e.target.files?.[0])return;const d=new FormData();d.append('file',e.target.files[0]);setBusy(true);await run(()=>api(base+'/sources/upload','POST',d));setBusy(false)}}/></label>}
function JobsPanel(){const {base,run}=useApp();const {t}=useTranslation();const jobs=useQuery<any[]>({queryKey:[base,'jobs'],queryFn:()=>api(base+'/jobs'),refetchInterval:4000});return <div className="jobs-panel">{jobs.data?.slice(0,8).map(j=><div key={j.id} className="job-row"><span className={'mini-dot '+(j.status==='Failed'?'red':'')}/><div><strong>{j.kind} · {j.stage}</strong><small>{j.error||j.status}</small><div className="progress-track"><i style={{width:j.progress+'%'}}/></div></div>{j.status==='Failed'?<button className="icon-btn" aria-label={t('retry')} onClick={()=>run(()=>api(base+'/jobs/'+j.id+'/retry','POST',{}))}><RefreshCw size={14}/></button>:j.status==='Running'||j.status==='Queued'?<button className="icon-btn" aria-label={t('cancel')} onClick={()=>run(()=>api(base+'/jobs/'+j.id+'/cancel','POST',{}))}><X size={14}/></button>:<Check size={14}/>}</div>)}</div>}
function Knowledge(){
 const {base,run,filter}=useApp();const {t}=useTranslation();const nav=useNavigate();const loc=useLocation();const id=loc.pathname.split('/documents/')[1];const sources=useItems('source');const documents=useItems('document');const templates=useItems('template');const selected=documents.data?.find(d=>d.id===id);const [tab,setTab]=useState('sources');const [modal,setModal]=useState<string|null>(null);const [source,setSource]=useState<Item|null>(null);const [versions,setVersions]=useState<any>(null);const [compare,setCompare]=useState('');
 return <><PageHeader eyebrow="KNOWLEDGE THAT MOVES YOU FORWARD" title={selected?.title||t('knowledge')} description={t('ocrNotice')} actions={<><Button variant="outline" onClick={()=>setModal('crawl')}><Globe size={15}/>{t('crawl')}</Button><Button onClick={()=>setModal('generate')}><Sparkles size={16}/>{t('generate')}</Button></>}/>{selected?<><button className="text-link" onClick={()=>nav(base+'/knowledge')}><ArrowLeft size={14}/>{t('documents')}</button><DocumentEditor key={selected.id} doc={selected} onVersions={async()=>{const r=await run(()=>api(base+'/history/'+selected.id));if(r)setVersions(r)}}/></>:<><div className="tabs">{['sources','documents','generate'].map(s=><button className={tab===s?'active':''} key={s} onClick={()=>s==='generate'?setModal('generate'):setTab(s)}>{t(s)}<span>{s==='sources'?sources.data?.length:s==='documents'?documents.data?.length:''}</span></button>)}</div>{tab==='sources'?<div className="knowledge-grid"><section><UploadPanel/><div className="source-list card"><div className="table-head"><span>{t('name')}</span><span>{t('status')}</span><span/></div>{sources.data?.filter(s=>s.status!=='Deleted'&&s.title.toLowerCase().includes(filter.toLowerCase())).map(s=><div className="source-row" key={s.id}><button className="source-name" onClick={()=>setSource(s)}><span className="file-icon"><FileText size={20}/></span><div><strong>{s.title}</strong><small>{s.data.snapshot?t('snapshot'):s.data.type||t('source')}</small></div></button><Badge tone={s.status==='Ready'?'green':s.status==='Failed'||s.status==='Quarantined'?'red':'amber'}>{s.status}</Badge><button className="icon-btn" aria-label={t('delete')} onClick={()=>run(()=>api(base+'/sources/'+s.id,'DELETE',{}))}><Trash2 size={15}/></button></div>)}</div></section><aside className="card"><div className="card-heading"><h3>{t('jobs')}</h3><Activity size={17}/></div><JobsPanel/></aside></div>:<div className="document-grid">{documents.data?.filter(d=>d.title.toLowerCase().includes(filter.toLowerCase())).map(d=><button className="document-card card" key={d.id} onClick={()=>nav(base+'/knowledge/documents/'+d.id)}><div className="document-sheet"><FileText size={35}/><div/><div/><div/><div/></div><Badge>{d.data.language?.toUpperCase()||'JA'} · v{d.version}</Badge><h3>{d.title}</h3><small>{d.status}</small></button>)}<button className="card new-preview" onClick={()=>setModal('generate')}><Plus size={26}/>{t('newDoc')}</button></div>}</>}{modal==='crawl'&&<FormModal title={t('crawl')} fields={[{name:'url',label:t('website'),required:false},{name:'mode',label:t('source'),options:['Offline snapshot','Live public website','Injection test fixture']}]} onClose={()=>setModal(null)} onSubmit={async d=>{await api(base+'/sources/crawl','POST',{url:d.url,fixture:d.mode!=='Live public website',injection:d.mode==='Injection test fixture'});client.invalidateQueries()}}/>}{modal==='generate'&&<FormModal title={t('generate')} fields={[{name:'title',label:t('title'),value:i18n.language==='ja'?'会社紹介':'Company introduction'},{name:'template',label:t('template'),options:templates.data?.map(t=>t.title)||['Company introduction','Business plan']},{name:'prompt',label:t('prompt'),type:'textarea',value:i18n.language==='ja'?'確認済み情報を使って会社紹介を書いてください。':'Write a company introduction using confirmed evidence.'},{name:'language',label:t('language'),options:['ja','en'],value:i18n.language},{name:'length',label:t('length'),options:['300 words','600 words','1000 words','2000 words']},{name:'outline',label:t('outline'),type:'textarea',value:'1. Company overview\n2. Products and capabilities\n3. Customers\n4. Opportunities and assumptions'}]} onClose={()=>setModal(null)} onSubmit={async d=>{const doc=await api(base+'/records/document','POST',{title:d.title,data:{template:d.template,outline:d.outline,language:d.language,content:'# '+d.title+'\n\n'+d.outline,request:d}});nav(base+'/knowledge/documents/'+doc.id);client.invalidateQueries()}}/>}{source&&<Modal title={source.title} onClose={()=>setSource(null)} wide><Badge tone={source.status==='Ready'?'green':'amber'}>{source.status}</Badge>{source.data.flagged&&<p className="error">Instruction-like content quarantined. Excluded from retrieval.</p>}{source.data.previous_source_id&&<details><summary>{t('history')}</summary><pre className="source-text">{source.data.diff||'No source text changes'}</pre></details>}<div className="source-text">{source.data.text||source.data.error||t('processing')}</div><div className="modal-actions">{source.data.type==='upload'&&<Button variant="outline" onClick={()=>download(base+'/sources/'+source.id+'/file')}>{t('view')}</Button>}{source.data.type==='url'&&<Button variant="outline" onClick={()=>run(()=>api(base+'/sources/'+source.id+'/reanalyze','POST',{}))}>{t('analysis')}</Button>}<Button variant="outline" onClick={()=>run(()=>api(base+'/sources/'+source.id+'/reindex','POST',{}))}>{t('refresh')}</Button></div></Modal>}{versions&&selected&&<Modal title={t('history')} onClose={()=>setVersions(null)} wide>{versions.map((r:any)=><div className="history-item" key={r.id}><div className="row-actions"><Badge>v{r.version}</Badge><small>{new Date(r.time).toLocaleString(i18n.language)}</small><Button variant="outline" onClick={()=>setCompare(r.snapshot.data.content||'')}>{t('compare')}</Button><Button onClick={()=>run(()=>api(base+'/documents/'+selected.id+'/restore/'+r.id,'POST',{}))}>{t('restore')}</Button></div></div>)}{compare&&<div className="compare-grid"><div><h4>{t('history')}</h4><Markdown text={compare}/></div><div><h4>v{selected.version}</h4><Markdown text={selected.data.content||''}/></div></div>}</Modal>}</>
}
function DocumentEditor({doc,onVersions}:{doc:Item,onVersions:()=>void}){
 const {base,run}=useApp();const {t}=useTranslation();const facts=useItems('fact');const [busy,setBusy]=useState(false);const [comment,setComment]=useState(false);const [insert,setInsert]=useState(false);const [markers,setMarkers]=useState(true);const editor=useEditor({extensions:[StarterKit],content:doc.data.rich_html||'<p>'+String(doc.data.content||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('\n','</p><p>')+'</p>'});
 useEffect(()=>{if(editor)editor.commands.setContent(doc.data.rich_html||'<p>'+String(doc.data.content||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('\n','</p><p>')+'</p>')},[doc.version,editor]);
 const save=async()=>{if(!editor)return false;setBusy(true);const result=await run(()=>api(base+'/records/'+doc.id,'PATCH',{version:doc.version,data:{content:editor.getText(),rich_html:editor.getHTML()}}));setBusy(false);return !!result};
 const action=async(type:string)=>{if(!editor)return;const saved=await save();if(!saved)return;const text=editor.state.doc.textBetween(editor.state.selection.from,editor.state.selection.to,'\n')||editor.getText();await run(()=>api(base+'/documents/'+doc.id+'/generate','POST',{prompt:(type==='translate'?'Translate into '+(doc.data.language==='ja'?'English':'Japanese'):type==='table'?'Build a table from the selected knowledge sources':type)+' the selected text. Preserve citations and assumption markers.',selection:text,language:type==='translate'?(doc.data.language==='ja'?'en':'ja'):doc.data.language}));};
 return <div className="editor-layout"><section className="card editor-card"><div className="editor-toolbar"><button onClick={()=>editor?.chain().focus().toggleBold().run()}><b>B</b></button><button onClick={()=>editor?.chain().focus().toggleItalic().run()}><i>I</i></button><button onClick={()=>editor?.chain().focus().toggleHeading({level:2}).run()}>H2</button><button onClick={()=>editor?.chain().focus().toggleBulletList().run()}>• List</button><span/><Button variant="ghost" onClick={onVersions}><History size={15}/>{t('history')}</Button><Button disabled={busy} onClick={save}><Check size={15}/>{t('save')}</Button></div><div className="editor-paper"><div className="document-meta">{doc.data.template||t('documents')} · {doc.data.language?.toUpperCase()} · v{doc.version}</div><h1>{doc.title}</h1><EditorContent editor={editor}/></div><div className="editor-export"><label className="check-label"><input type="checkbox" checked={markers} onChange={e=>setMarkers(e.target.checked)}/>{t('provenance')}</label>{['pdf','docx','md'].map(format=><Button variant="outline" key={format} onClick={()=>download(base+'/export/document/'+doc.id+'?format='+format+'&markers='+markers)}><Download size={14}/>{format.toUpperCase()}</Button>)}</div></section><aside><div className="card ai-actions"><div className="card-heading"><h3><Sparkles size={17}/>{t('generate')}</h3></div><p>{t('human')}</p>{['rewrite','shorten','expand','translate','table'].map(a=><button key={a} onClick={()=>action(a)}>{t(a)}<ArrowUpRight size={15}/></button>)}<button onClick={()=>setInsert(true)}>{t('insertFact')}<Plus size={15}/></button><Button className="full" onClick={()=>run(()=>api(base+'/documents/'+doc.id+'/generate','POST',{prompt:doc.data.request?.prompt||doc.title,language:doc.data.language,outline:doc.data.outline,length:doc.data.request?.length}))}>{t('approveOutline')}</Button><Button variant="outline" className="full" onClick={()=>run(()=>api(base+'/documents/'+doc.id+'/save-source','POST',{}))}>{t('saveSource')}</Button></div><div className="card comments-card"><div className="card-heading"><h3>{t('comments')}</h3><button className="icon-btn" onClick={()=>setComment(true)}><Plus size={16}/></button></div>{doc.data.comments?.map((c:any,i:number)=><div className="comment" key={i}><strong>{c.author}</strong><p>{c.text}</p></div>)}</div><JobsPanel/><div className="row-actions"><Rating target={doc.id} feature="document"/></div></aside>{comment&&<FormModal title={t('comments')} fields={[{name:'text',label:t('text'),type:'textarea'}]} onClose={()=>setComment(false)} onSubmit={async d=>{await api(base+'/records/'+doc.id,'PATCH',{data:{comments:[...(doc.data.comments||[]),{author:'Member',text:d.text,time:new Date().toISOString()}]}});client.invalidateQueries()}}/>}{insert&&<Modal title={t('insertFact')} onClose={()=>setInsert(false)}>{facts.data?.filter(f=>f.status==='Confirmed').map(f=><button className="list-row" key={f.id} onClick={()=>{editor?.chain().focus().insertContent(' '+f.title+': '+f.data.value+' [F:'+f.id+'] ').run();setInsert(false)}}>{f.title}: {f.data.value}</button>)}</Modal>}</div>
}
const stageNames=['All','Inward','Warehouse','Kitting','Assembly','Final inspection','Packaging','Logistics','Planning','Quality','Maintenance','R&D','Sales'];
function UseCases(){
 const {base,filter,run}=useApp();const {t}=useTranslation();const nav=useNavigate();const lib=useQuery<any[]>({queryKey:['library'],queryFn:()=>api('/library')});const mine=useItems('usecase');const recs=useQuery<any[]>({queryKey:[base,'recommendations'],queryFn:()=>api(base+'/recommendations')});const [tab,setTab]=useState('library');const [stage,setStage]=useState('All');const [horizon,setHorizon]=useState('All');const [level,setLevel]=useState('All');const [entry,setEntry]=useState('All');const [detail,setDetail]=useState<any>(null);const [custom,setCustom]=useState(false);const [edit,setEdit]=useState<Item|null>(null);
 const items=(lib.data||[]).filter(l=>(stage==='All'||l.stage===stage)&&(horizon==='All'||l.horizon===horizon)&&(level==='All'||l.level===level)&&(entry==='All'||l.entry.includes(entry))&&JSON.stringify(l).toLowerCase().includes(filter.toLowerCase()));
 const move=async(id:string,quadrant:string)=>run(()=>api(base+'/records/'+id,'PATCH',{data:{quadrant}}));
 const makeCharter=async(u:Item)=>run(async()=>{const doc=await api(base+'/records/document','POST',{title:u.title+' — Charter',data:{template:'AI use-case charter',language:i18n.language,content:'# '+u.title+'\n\n'+JSON.stringify(u.data,null,2)}});await api(base+'/documents/'+doc.id+'/generate','POST',{prompt:'Draft a one-page use-case charter. Classify step and autonomy level and list prerequisites. Treat user fields as stated input:\n'+JSON.stringify(u.data),language:i18n.language});nav(base+'/knowledge/documents/'+doc.id)});
 return <><PageHeader eyebrow="PRACTICAL POSSIBILITIES FOR YOUR FACTORY" title={t('usecases')} description={t('quickSub')} actions={<Button onClick={()=>setCustom(true)}><Plus size={16}/>{t('custom')}</Button>}/><div className="tabs">{['library','recommend','mine','map','roadmap','method'].map(s=><button key={s} className={tab===s?'active':''} onClick={()=>setTab(s)}>{t(s)}</button>)}</div>{tab==='library'||tab==='recommend'?<><div className="filter-row">{[[stage,setStage,stageNames],[horizon,setHorizon,['All','H1','H2','H3']],[level,setLevel,['All','L0','L1','L2','L3','L4','L5']],[entry,setEntry,['All','Software only','Camera based','Machine IoT']]].map(([value,set,options]:any,i)=><select key={i} value={value} onChange={e=>set(e.target.value)} aria-label={t(['stage','horizon','level','entry'][i])}>{options.map((s:string)=><option key={s}>{s}</option>)}</select>)}<span className="push subtle">{tab==='library'?items.length:recs.data?.length} {t('usecases')}</span></div><div className="usecase-grid">{(tab==='recommend'?(recs.data||[]).map(r=>({...r.use_case,recommendation:r})):items).map((l:any)=><article className="card usecase-card" key={l.id}><div className="usecase-top"><div className="usecase-icon"><Sparkles size={20}/></div><Badge tone={l.horizon==='H1'?'green':'blue'}>{l.horizon}</Badge><Badge>{l.level}</Badge></div><small className="eyebrow">{l.stage}</small><h3><button onClick={()=>setDetail(l)}>{i18n.language==='ja'?l.title_ja:l.title}</button></h3><p>{i18n.language==='ja'?l.data.problem_ja:l.data.problem}</p><div className="usecase-tags"><span>{l.entry}</span><span>{l.status}</span></div>{l.recommendation&&<div className="recommendation-why"><ShieldCheck size={14}/>{l.recommendation.rationale[i18n.language]}<small>{l.recommendation.fact_ids.length} {t('confirmed')}</small></div>}<div className="small-note">{t('draft')}</div><div className="row-actions"><Button variant="outline" onClick={()=>run(()=>api(base+'/usecases/add/'+l.id,'POST',{}))}><Plus size={14}/>{t('add')}</Button>{l.recommendation&&<Rating target={l.id} feature="recommendation"/>}</div></article>)}</div></>:tab==='mine'?<div className="usecase-grid">{mine.data?.map(u=><article className="card usecase-card" key={u.id}><Badge>{u.data.horizon||'H1'} · {u.data.level||'L1'}</Badge><h3>{u.title}</h3><p>{u.data.problem||u.data.charter}</p><div className="row-actions"><Button variant="outline" onClick={()=>setEdit(u)}>{t('edit')}</Button><Button onClick={()=>makeCharter(u)}><FileText size={14}/>{t('charter')}</Button><Rating target={u.id} feature="usecase"/></div></article>)}<button className="card new-preview" onClick={()=>setCustom(true)}><Plus size={28}/>{t('custom')}</button></div>:tab==='roadmap'?<><div className="section-heading"><p>{t('impact')} × {t('readiness')} · {t('inferred')}</p><Button variant="outline" onClick={()=>download(base+'/export/roadmap/current?format=pdf')}><Download size={15}/>{t('export')}</Button></div><div className="roadmap-board">{['Quick wins','Strategic bets','Momentum builders','Later'].map((q,i)=><section key={q} className={'quadrant q'+i} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();move(e.dataTransfer.getData('text/plain'),q)}}><div className="card-heading"><h3>{q}</h3><Badge>{mine.data?.filter(u=>u.data.quadrant===q).length||0}</Badge></div>{mine.data?.filter(u=>(u.data.quadrant||'Later')===q).map(u=><div className="roadmap-item" key={u.id} draggable onDragStart={e=>e.dataTransfer.setData('text/plain',u.id)}><GripVertical size={15}/><button onClick={()=>setEdit(u)}>{u.title}</button><Badge>{u.data.horizon}</Badge></div>)}</section>)}</div><section className="card timeline"><h3>{t('horizon')}</h3>{['H1','H2','H3'].map((h,i)=><div className="timeline-row" key={h}><strong>{h}<small>{new Date().getFullYear()+i}</small></strong><div>{mine.data?.filter(u=>u.data.horizon===h).map(u=><span key={u.id}>{u.title}{u.data.dependencies?.length?<small>Needs data created by {u.data.dependencies.map((d:string)=>mine.data?.find(x=>x.id===d)?.title).join(', ')}</small>:null}</span>)}</div></div>)}</section></>:tab==='map'?<><div className="factory-map">{stageNames.slice(1,8).map((s,i)=><button key={s} className={'factory-stage '+(stage===s?'active':'')} onClick={()=>setStage(s)}><span>0{i+1}</span><Building2 size={28}/><strong>{s}</strong><small>{lib.data?.filter(l=>l.stage===s).length} {t('usecases')}</small>{i<6&&<ArrowRight className="flow-arrow" size={18}/>}</button>)}</div><div className="lane-row">{stageNames.slice(8).map(s=><Button variant="outline" key={s} onClick={()=>setStage(s)}>{s}</Button>)}</div><section className="card learning"><Badge tone="amber">{t('draft')}</Badge><h2>{stage==='All'?'Assembly / Machining':stage}</h2><p>{i18n.language==='ja'?'工程の記録と作業を整理し、人による確認を維持してAIの機会を検討します。':'Map human operations and existing records, then identify AI opportunities while keeping human review.'}</p><h4>{t('systems')}</h4><p>Paper · Spreadsheet · ERP / MES records · Camera · Sensor</p><h4>{t('dataNeeded')}</h4><p>{lib.data?.filter(l=>stage==='All'||l.stage===stage).slice(0,3).map(l=>l.data.data_needed).join(' · ')}</p></section></>:<section className="card learning"><Badge tone="amber">{t('draft')}</Badge><h2>Atomic Assessment</h2><p>{i18n.language==='ja'?'まず測定し、次にモデル化します。工場の判断とデータの流れを理解してから、AIの活用を計画します。':'Measure before modelling. Understand the factory’s decisions and data flow before planning AI use cases.'}</p><div className="method-steps">{['KPI alignment','Interviews & Gemba','Machine workflow','Document review','Processing & report'].map((s,i)=><div key={s}><span>0{i+1}</span><h3>{s}</h3></div>)}</div><h3>Descriptive → Predictive → Prescriptive → Autonomous</h3><p>L0 Manual · L1 Assisted · L2 Partial · L3 Conditional · L4 High · L5 Full</p><p>H1 Quick wins · H2 Strategic bets · H3 Disruptive solutions</p><h3>Value principles</h3><p>Measured before modelled · Targets derived · Haircuts applied · Overlaps combined</p><div className="warning">The three report outcomes and detailed stage teaching material require Atomic Loops source material and approval.</div></section>}{detail&&<Modal title={i18n.language==='ja'?detail.title_ja:detail.title} onClose={()=>setDetail(null)} wide><Badge tone="amber">{t('draft')}</Badge><dl className="detail-list">{['problem','how','systems','data_needed','prerequisites','success'].map(k=><div key={k}><dt>{k.replaceAll('_',' ')}</dt><dd>{detail.data[k+(i18n.language==='ja'?'_ja':'')]||detail.data[k]}</dd></div>)}</dl><Button onClick={()=>run(()=>api(base+'/usecases/add/'+detail.id,'POST',{}))}>{t('add')}</Button></Modal>}{(custom||edit)&&<FormModal title={t(custom?'custom':'edit')} fields={[{name:'title',label:t('title'),value:edit?.title},{name:'problem',label:t('problem'),type:'textarea',value:edit?.data.problem},{name:'stage',label:t('stage'),options:stageNames.slice(1),value:edit?.data.stage},{name:'affected',label:t('affected'),value:edit?.data.affected},{name:'capture',label:t('capture'),options:['Paper','Spreadsheet','System','Sensor'],value:edit?.data.capture},{name:'systems',label:t('systems'),value:edit?.data.systems},{name:'outcome',label:t('outcome'),value:edit?.data.outcome},{name:'kpi',label:t('kpi'),value:edit?.data.kpi},{name:'horizon',label:t('horizon'),options:['H1','H2','H3'],value:edit?.data.horizon},{name:'quadrant',label:t('roadmap'),options:['Quick wins','Strategic bets','Momentum builders','Later'],value:edit?.data.quadrant},{name:'impact',label:t('impact')+' (1–5)',type:'number',value:String(edit?.data.impact||3)},...['data','process','people','systems'].map(k=>({name:'readiness_'+k,label:t('readiness')+' '+k+' (1–5, Inferred)',type:'number',value:String(edit?.data.readiness?.[k]||2)})),{name:'year',label:t('year'),type:'number',value:String(edit?.data.year||new Date().getFullYear())}]} onClose={()=>{setCustom(false);setEdit(null)}} onSubmit={async d=>{const data={...d,impact:Number(d.impact),readiness:{data:Number(d.readiness_data),process:Number(d.readiness_process),people:Number(d.readiness_people),systems:Number(d.readiness_systems)},readiness_provenance:'Inferred',level:edit?.data.level||'L1',year:Number(d.year)||new Date().getFullYear(),dependencies:edit?.data.dependencies||[]};await api(base+'/records/'+(edit?edit.id:'usecase'),edit?'PATCH':'POST',{title:d.title,data});client.invalidateQueries()}}/>}</>
}
function FeedbackModal({onClose,target}:{onClose:()=>void,target?:string}){const {base,session,setNotice}=useApp();const {t}=useTranslation();const [file,setFile]=useState<File|null>(null);return <FormModal title={t('feedback')} onClose={onClose} fields={[{name:'category',label:t('category'),options:['bug','idea','confusing','wrong','praise']},{name:'text',label:t('text'),type:'textarea'}]} onSubmit={async d=>{let screenshot_id='';if(file){const form=new FormData();form.append('file',file);const s=await api(base+'/sources/upload','POST',form);screenshot_id=s.source.id}await api(base+'/records/feedback','POST',{title:d.category,data:{...d,page:location.pathname,language:i18n.language,role:session.user.role,target_id:target,screenshot_id}});client.invalidateQueries();setNotice(t('feedbackThanks'))}}><label className="field"><span>{t('screenshot')}</span><input type="file" accept="image/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label></FormModal>}
function FeedbackPage(){const {t}=useTranslation();const items=useItems('feedback');const [add,setAdd]=useState(false);return <><PageHeader title={t('feedback')} actions={<Button onClick={()=>setAdd(true)}><Plus size={15}/>{t('feedback')}</Button>}/>{items.data?.map(f=><article className="card feedback-item" key={f.id}><Badge>{f.status==='New'?'Received':f.status}</Badge><h3>{f.title}</h3><p>{f.data.text}</p>{f.data.reply&&<blockquote>{f.data.reply}</blockquote>}<small>{f.data.page}</small></article>)}{add&&<FeedbackModal onClose={()=>setAdd(false)}/>}</>}
function WorkspaceSettings(){
 const {base,run,session}=useApp();const {t}=useTranslation();const {data}=useQuery({queryKey:[base,'settings'],queryFn:()=>api(base+'/settings')});const invitations=useItems('invitation');const consents=useItems('consent');const [form,setForm]=useState<string|null>(null);const [selected,setSelected]=useState<string[]>([]);const [sharingDirty,setSharingDirty]=useState(false);const [mfa,setMfa]=useState<any>(null);const [mfaCodes,setMfaCodes]=useState<string[]>([]);
 useEffect(()=>{if(data?.workspace&&!sharingDirty)setSelected(data.workspace.data.sharing||['overview','products'])},[data,sharingDirty]);
 if(!data)return <Empty text={t('loading')}/>;
 return <><PageHeader eyebrow="YOUR TEAM. YOUR DATA. YOUR CONTROL." title={t('settings')} actions={<Button variant="outline" onClick={()=>download(base+'/export-all')}><Download size={15}/>{t('downloadAll')}</Button>}/><div className="settings-grid"><section className="card settings-card"><h3>{t('company')}</h3><label className="field"><span>Logo</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={async e=>{if(!e.target.files?.[0])return;const form=new FormData();form.append('file',e.target.files[0]);const result=await run(()=>api(base+'/sources/upload','POST',form));if(result)await run(()=>api(base+'/settings','PATCH',{data:{logo_source_id:result.source.id}}))}}/></label><form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));run(()=>api(base+'/settings','PATCH',{title:f.name,data:{language:f.language,instructions:f.instructions,retention_months:Number(f.retention)}}))}}><label className="field"><span>{t('name')}</span><input name="name" defaultValue={data.workspace.name}/></label><label className="field"><span>{t('language')}</span><select name="language" defaultValue={data.workspace.language}><option>ja</option><option>en</option></select></label><label className="field"><span>{t('instructions')}</span><textarea name="instructions" defaultValue={data.workspace.data.instructions}/></label><label className="field"><span>{t('retention')}</span><input type="number" min="1" max="120" name="retention" defaultValue={data.workspace.data.retention_months||24}/></label><Button>{t('save')}</Button></form></section><section className="card settings-card"><h3>{t('sharing')}</h3>{sections.map(s=><label className="context-toggle" key={s}>{t(s)}<input type="checkbox" checked={selected.includes(s)} onChange={e=>{setSharingDirty(true);setSelected(e.target.checked?[...selected,s]:selected.filter(x=>x!==s))}}/></label>)}<Button onClick={()=>run(()=>api(base+'/settings','PATCH',{data:{sharing:selected}}))}>{t('save')}</Button><h3>{t('consent')}</h3><label className="context-toggle"><span>{t('consent')}</span><input type="checkbox" defaultChecked={data.workspace.data.feedback_consent} onChange={e=>run(()=>api(base+'/records/consent','POST',{title:'Feedback use consent',data:{kind:'feedback_use',value:e.target.checked}}))}/></label><small>{t('draft')}</small></section><section className="card settings-card"><div className="card-heading"><h3>{t('member')}</h3><Button variant="outline" onClick={()=>setForm('invite')}><Plus size={14}/>{t('invite')}</Button></div>{data.members.map((m:any)=><div className="list-row" key={m.user.id}><div className="avatar small">{m.user.name[0]}</div><div><strong>{m.user.name}</strong><small>{m.role} · {m.user.email}</small></div>{m.role!=='Company Admin'&&<button className="icon-btn" onClick={()=>run(()=>api(base+'/members/'+m.user.id,'DELETE',{}))}><X size={14}/></button>}</div>)}<Button variant="ghost" onClick={()=>setForm('grant')}>{t('grant')}</Button>{invitations.data?.filter(i=>i.status==='Pending').map(i=><div className="list-row" key={i.id}><span>{i.data.email}</span><Badge>{i.status}</Badge><Button variant="ghost" onClick={()=>run(()=>api(base+'/invitations/'+i.id+'/resend','POST',{}))}>{t('send')}</Button><Button variant="ghost" onClick={()=>run(()=>api(base+'/invitations/'+i.id+'/revoke','POST',{}))}>{t('cancel')}</Button></div>)}</section><section className="card settings-card"><h3>{t('security')}</h3><div className="warning">{session.demo_mfa_bypass?t('mfaNotice'):t('human')}</div><Button variant="outline" onClick={async()=>{const r=await run(()=>api('/auth/mfa/enroll','POST',{}));if(r)setMfa(r)}}>{t('enroll')}</Button><label className="field"><span>{t('digest')}</span><select defaultValue={session.user.preferences?.digest||'daily'} onChange={e=>run(()=>api('/auth/preferences','PATCH',{digest:e.target.value}))}><option value="daily">{t('daily')}</option><option value="weekly">{t('weekly')}</option><option value="off">{t('off')}</option></select></label><h3>{t('deletion')}</h3><Button variant="danger" onClick={()=>setForm('deletion')}>{t('deletion')}</Button><p className="subtle">Export your data before requesting deletion. This records a request for authorised review.</p></section></div>{form&&<FormModal title={t(form==='invite'?'invite':form==='grant'?'grant':'deletion')} fields={form==='invite'?[{name:'email',label:t('email'),type:'email'}]:form==='grant'?[{name:'email',label:t('email'),type:'email'},{name:'role',label:t('role'),options:['Coordinator read','Coordinator comment','Member']}]:[{name:'reason',label:t('reason'),type:'textarea'}]} onClose={()=>setForm(null)} onSubmit={async d=>{await api(base+(form==='invite'?'/invitations':form==='grant'?'/members':'/records/deletion'),'POST',form==='deletion'?{title:'Deletion request',data:d}:d);client.invalidateQueries()}}/>}{mfa&&<FormModal title={t('security')} fields={[{name:'code',label:t('code')}]} onClose={()=>setMfa(null)} onSubmit={async d=>{const r=await api('/auth/mfa/verify','POST',d);setMfaCodes(r.recovery_codes||[]);client.invalidateQueries()}}><div className="codebox">{mfa.secret}</div><p className="subtle">Store the secret in an authenticator app, then enter its current code.</p></FormModal>}{mfaCodes.length>0&&<Modal title="Recovery codes" onClose={()=>setMfaCodes([])}><pre>{mfaCodes.join('\n')}</pre></Modal>}</>
}
function Admin(){
 const {session,run,filter}=useApp();const {t}=useTranslation();const loc=useLocation();const nav=useNavigate();const page=loc.pathname.split('/')[2]||'portfolio';const id=loc.pathname.split('/')[3];const [form,setForm]=useState<any>(null);const [detail,setDetail]=useState<any>(null);const [sort,setSort]=useState('name');
 const companies=useQuery<any[]>({queryKey:['admin','companies'],queryFn:()=>api('/admin/companies')});const dash=useQuery({queryKey:['admin','dashboard'],queryFn:()=>api('/admin/dashboard')});const lib=useQuery<any[]>({queryKey:['library'],queryFn:()=>api('/library')});const items=useQuery<any[]>({queryKey:['admin',page],queryFn:()=>api('/admin/'+page),enabled:['audit','feedback','outbox'].includes(page)});
 useEffect(()=>{if(page==='companies'&&id)run(()=>api('/admin/companies/'+id)).then((r:any)=>r&&setDetail(r))},[id]);
 const createFields=[{name:'title',label:t('name')},{name:'name_ja',label:t('titleJa')},{name:'slug',label:t('slug')},{name:'industry',label:t('industry')},{name:'size_band',label:t('employee')},{name:'email',label:t('email'),type:'email'},{name:'language',label:t('language'),options:['ja','en']}];
 return <><PageHeader eyebrow="MIYAZAKI OPERATOR CONSOLE" title={t(page==='portfolio'?'portfolio':page)} description={t('human')} actions={page==='companies'?<><select aria-label="Sort companies" value={sort} onChange={e=>setSort(e.target.value)}><option value="name">{t('name')}</option><option value="completeness">{t('completeness')}</option><option value="recent">{t('recent')}</option></select><Button variant="outline" onClick={()=>download('/admin/export/companies')}><Download size={15}/>CSV</Button><Button onClick={()=>setForm({type:'company'})}><Plus size={15}/>{t('createCompany')}</Button></>:page==='library'&&session.user.role==='Platform Admin'?<Button onClick={()=>setForm({type:'library'})}><Plus size={15}/>{t('create')}</Button>:page==='feedback'?<Button variant="outline" onClick={()=>download('/admin/export/feedback')}>CSV</Button>:null}/>{page==='portfolio'?<><div className="hero-panel admin-hero"><div className="hero-copy"><Badge tone="light">PORTFOLIO INTELLIGENCE</Badge><h2>{t('quick')}</h2><p>{t('evidence')}</p></div><div className="hero-visual"><Building2 size={95} strokeWidth={0.7}/></div></div><div className="stats-grid"><Stat label={t('total')} value={dash.data?.companies||0} icon={Building2}/><Stat label={t('active')} value={dash.data?.weekly_active||0} icon={Activity}/><Stat label={t('feedback')} value={dash.data?.feedback||0} icon={MessageSquare}/><Stat label={t('positive')} value={(dash.data?.positive_rate||0)+'%'} icon={ThumbsUp}/></div><div className="overview-grid"><section className="card"><div className="card-heading"><h3>{t('funnel')}</h3><GitBranch size={17}/></div><div className="funnel">{Object.entries(dash.data?.funnel||{}).map(([key,value]:any,i)=><div key={key}><span>{key.replaceAll('_',' ')}</span><div style={{width:Math.max(20,100-i*18)+'%'}}><strong>{value}</strong></div></div>)}</div></section><section className="card"><div className="card-heading"><h3>{t('industry')}</h3><Building2 size={17}/></div>{Object.entries(dash.data?.industries||{}).map(([key,value]:any)=><div className="list-row" key={key}><strong>{key}</strong><Badge>{value}</Badge></div>)}</section></div><div className="section-heading"><h2>{t('companies')}</h2><button className="text-link" onClick={()=>nav('/admin/companies')}>{t('all')}<ArrowRight size={15}/></button></div><div className="card company-table">{companies.data?.map(c=><button className="company-row" key={c.id} onClick={()=>nav('/admin/companies/'+c.id)}><div className="workspace-monogram">{c.name[0]}</div><div><strong>{c.name}</strong><small>{c.industry}</small></div><Badge tone="green">{c.status}</Badge><span>{c.completeness}%</span><ArrowUpRight size={16}/></button>)}</div></>:page==='companies'?<div className="card company-table"><div className="company-row table-head"><span/><strong>{t('company')}</strong><span>{t('status')}</span><span>{t('completeness')}</span><span/></div>{companies.data?.filter(c=>JSON.stringify(c).toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='completeness'?b.completeness-a.completeness:new Date(b.last_activity).getTime()-new Date(a.last_activity).getTime()).map(c=><div className="company-row" key={c.id}><div className="workspace-monogram">{c.name[0]}</div><button className="table-link" onClick={()=>nav('/admin/companies/'+c.id)}><strong>{c.name}</strong><small>{c.industry} · {c.name_ja}</small></button><Badge tone={c.status==='Deactivated'?'red':'green'}>{c.status}</Badge><span>{c.completeness}%</span><div className="row-actions"><button className="icon-btn" aria-label={t('settings')} onClick={()=>setForm({type:'budget',item:c})}><Settings size={15}/></button><Button variant="ghost" onClick={()=>run(()=>api('/admin/companies/'+c.id,'PATCH',{status:c.status==='Deactivated'?'Active':'Deactivated'}))}>{c.status==='Deactivated'?'Reactivate':'Deactivate'}</Button></div></div>)}</div>:page==='library'?<><p className="small-note">{t('draft')} · {lib.data?.length} cards</p><div className="card library-table">{lib.data?.filter(l=>JSON.stringify(l).toLowerCase().includes(filter.toLowerCase())).map(l=><div className="list-row" key={l.id}><div className="preview-icon"><Layers size={17}/></div><div><strong>{l.title}</strong><small>{l.title_ja} · {l.stage} · {l.horizon} · {l.level}</small></div><Badge>{l.status}</Badge><Button variant="outline" onClick={()=>setForm({type:session.user.role==='Super Admin'?'review':'library',item:l})}>{t('edit')}</Button>{session.user.role==='Platform Admin'&&<Button onClick={()=>run(()=>api('/library/'+l.id,'PATCH',{status:l.status==='Draft'?'Review':'Published',version:l.version,data:{}}))}>{t(l.status==='Draft'?'reviewContent':'publish')}</Button>}</div>)}</div></>:page==='feedback'?<>{items.data?.filter(f=>JSON.stringify(f).toLowerCase().includes(filter.toLowerCase())).map(f=><article className="card feedback-item" key={f.id}><div className="card-heading"><Badge tone={f.status==='Addressed'?'green':'amber'}>{f.status}</Badge><small>{f.data.page}</small><Button variant="outline" onClick={()=>setForm({type:'feedback',item:f})}>{t('reply')}</Button></div><h3>{f.title}</h3><p>{f.data.text||f.data.correction||f.data.rating}</p>{f.data.reply&&<blockquote>{f.data.reply}</blockquote>}</article>)}</>:page==='audit'?<div className="card audit-table">{items.data?.filter(a=>JSON.stringify(a).toLowerCase().includes(filter.toLowerCase())).map(a=><div className="list-row" key={a.id}><ShieldCheck size={16}/><div><strong>{a.action}</strong><small>{a.target}</small></div><small>{new Date(a.time).toLocaleString(i18n.language)}</small></div>)}</div>:page==='outbox'?<>{items.data?.map(m=><article className="card feedback-item" key={m.id}><Badge>{m.data.language}</Badge><h3>{m.title}</h3><small>{m.data.recipient}</small><p className="codebox">{m.data.body}</p>{String(m.data.body).startsWith('/')&&<a className="btn outline" href={m.data.body} target="_blank" rel="noreferrer">{t('view')}<ExternalLink size={14}/></a>}</article>)}</>:null}{detail&&<Modal title={detail.workspace.name} onClose={()=>{setDetail(null);nav('/admin/companies')}} wide><p>{t('sharing')}</p>{detail.facts.map((f:Item)=><div className="list-row" key={f.id}><Badge>{f.data.provenance}</Badge><strong>{f.title}</strong><span>{f.data.value}</span></div>)}<div className="stats-grid">{Object.entries(detail.counts).map(([k,v]:any)=><Stat label={t(k==='usecase'?'usecases':k==='document'?'documents':k==='workflow'?'workflows':'chats')} value={v} icon={Layers} key={k}/>)}</div></Modal>}{form&&<FormModal title={t(form.type==='company'?'createCompany':form.type==='budget'?'budget':form.type==='feedback'?'reply':form.type==='review'?'approveJapanese':'library')} onClose={()=>setForm(null)} fields={form.type==='company'?createFields:form.type==='budget'?[{name:'budget',label:t('budget'),type:'number',value:String(form.item.token_budget)}]:form.type==='feedback'?[{name:'reply',label:t('reply'),type:'textarea',value:form.item.data.reply},{name:'status',label:t('status'),options:['New','In review','Addressed']}]:form.type==='review'?[{name:'comment',label:t('comments'),type:'textarea'},{name:'approve',label:t('approveJapanese'),options:['No','Yes']}]:[{name:'title',label:t('title'),value:form.item?.title},{name:'title_ja',label:t('titleJa'),value:form.item?.title_ja},{name:'stage',label:t('stage'),options:stageNames.slice(1),value:form.item?.stage},{name:'entry',label:t('entry'),options:['Software only','Camera based','Machine IoT'],value:form.item?.entry},{name:'horizon',label:t('horizon'),options:['H1','H2','H3'],value:form.item?.horizon},{name:'level',label:t('level'),options:['L0','L1','L2','L3','L4','L5'],value:form.item?.level},...['problem','how','systems','prerequisites','success','data_needed'].flatMap(k=>[{name:k,label:k.replaceAll('_',' ')+' EN',type:'textarea',value:form.item?.data[k]},{name:k+'_ja',label:k.replaceAll('_',' ')+' 日本語',type:'textarea',value:form.item?.data[k+'_ja']}])]} onSubmit={async d=>{if(form.type==='company')await api('/admin/companies','POST',{title:d.title,data:d});else if(form.type==='budget')await api('/admin/companies/'+form.item.id,'PATCH',{data:{token_budget:Number(d.budget)}});else if(form.type==='feedback')await api('/admin/feedback/'+form.item.id,'PATCH',{status:d.status,data:{reply:d.reply}});else if(form.type==='review')await api('/library/'+form.item.id,'PATCH',{data:{comment:d.comment,japanese_approved:d.approve==='Yes'}});else await api('/library'+(form.item?'/'+form.item.id:''),form.item?'PATCH':'POST',{title:d.title,version:form.item?.version,data:d});client.invalidateQueries()}}/>}</>
}
function Health(){const {t}=useTranslation();const h=useQuery({queryKey:['health'],queryFn:()=>api('/health')});return <div className="health-page"><a href="/" className="text-link"><ArrowLeft size={15}/>{t('return')}</a><PageHeader title={t('health')} description={t('noNetwork')} actions={<Button onClick={()=>h.refetch()}><RefreshCw size={16}/>{t('refresh')}</Button>}/><div className="card">{Object.entries(h.data||{}).map(([k,v])=><div className="list-row" key={k}><Activity size={17}/><strong>{k.replaceAll('_',' ')}</strong><span className="push">{typeof v==='object'?JSON.stringify(v):String(v)}</span></div>)}</div></div>}
createRoot(document.getElementById('root')!).render(<QueryClientProvider client={client}><BrowserRouter><App/></BrowserRouter></QueryClientProvider>);
